using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class HttpServer
{
    static void Main(string[] args)
    {
        // Création d'un objet HttpListener
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        // Début du serveur
        listener.Start();

        Console.WriteLine("Serveur HTTP démarré. Attente de requêtes...");

        while (true)
        {
            // Attendre une requête
            HttpListenerContext context = listener.GetContext();

            // Traitement de la requête
            HttpListenerRequest request = context.Request;
            if (request.Url.AbsolutePath == "/hello")
            {
                // Renvoi de la réponse
                HttpListenerResponse response = context.Response;
                response.StatusCode = 200;
                response.StatusDescription = "OK";
                byte[] responseBody = Encoding.UTF8.GetBytes("Hello");
                response.OutputStream.Write(responseBody, 0, responseBody.Length);
                response.OutputStream.Close();
            }
            else
            {
                // Renvoi d'une erreur 404 si la page n'est pas trouvée
                HttpListenerResponse response = context.Response;
                response.StatusCode = 404;
                response.StatusDescription = "Not Found";
            }
        }
    }
}
```
